("q924", PS, "Psikoz için risk altındaki ruhsal durumu (ARMS) çocukluk başlangıçlı şizofreniden ayırmak neden önemlidir?", ["Erken girişim psikozu önleyebilir ya da geciktirebilir", "İkisinin tedavisi tümüyle aynıdır", "ARMS'de tedavi gerekmez", "Ayrımın klinik değeri yoktur"], "Risk durumu tam bir psikotik bozukluk değildir.", I("B7.1")),
("q925", FA, "Dirençli şizofrenide klozapin denemesi en az ne kadar sürmelidir?", ["8 hafta", "3 gün", "1 hafta", "2 yıl"], "Günde 300–800 mg dozda. Yanıtsızlıkta madde kullanımı, başka ilaçlar ve bedensel hastalık dışlanmalıdır.", I("H.5.1")),
("q926", FA, "Uzun etkili olanzapin pamoat enjeksiyonundan sonra uyanıklık nasıl izlenmelidir?", ["En az 3 saat boyunca 30 dakikada bir", "Bir kez, ertesi gün", "İzlem gerekmez", "Haftada bir"], "Enjeksiyon sonrası deliryum-sedasyon sendromu riski nedeniyle; ilacın bir bölümü yanlışlıkla damara karışabilir.", I("H.5.1")),
("q927", GE, "“Amerikan uyku araştırmalarının babası” olarak bilinen kimdir?", ["Nathaniel Kleitman", "Sigmund Freud", "Ivan Pavlov", "Hans Selye"], "1920'lerde Chicago'da uyku-uyanıklık düzenlenmesini ve sirkadiyen ritimleri incelemeye başladı.", I("I.4")),
("q928", PS, "Kandaki alkol düzeyi 0,4'ün üzerine çıktığında tipik olarak ne olur?", ["Alkol zehirlenmesi, koma ve ölüm riski", "Hafif neşelenme", "Hiçbir etki", "Yalnızca uyku hâli"], "0,02–0,09 arası düzeyler tipik olarak duygudurum değişikliği yapar.", I("B4.1")),
("q929", GE, "Dünya Sağlık Örgütü tanımına göre ergenlik hangi yaşları kapsar?", ["10–19", "5–9", "13–15", "18–30"], "Çocukluk ile erişkinlik arasındaki geçiş dönemi.", I("B4.1")),
