("q931", NG, "Beş yaşından küçük, tanısı ve gidişi belirsiz çocuklarda dil güçlüğü için hangi terim önerilir?", ["Konuşma, dil ve iletişim gereksinimi (SLCN)", "Afazi", "Disleksi", "Seçici konuşmazlık"], "“Gecikme” teriminin kullanımı tartışmalıdır.", I("B1.4")),
("q932", NG, "Özgül öğrenme bozukluğunda etkilenen beceri, girişime karşın en az ne kadar süre belirgin bozuk olmalıdır?", ["6 ay", "1 hafta", "1 ay", "5 yıl"], "Okuma, yazma ya da aritmetik.", I("B1.6")),
("q933", PS, "Kronik yorgunluk sendromunun DSM-5'teki yeri nedir?", ["Ayrı bir kategori olarak yer almaz", "Depresyon bozuklukları bölümündedir", "Nörogelişimsel bozukluklar bölümündedir", "Kişilik bozuklukları bölümündedir"], "Bedensel belirti bozukluğuyla temel özellikleri paylaşır.", I("I.1")),
("q934", PS, "“Tıbben açıklanamayan belirtiler” terimi neyi anlatır?", ["Bilinen bir tıbbi hastalıkla açıklanamayan, rahatsız edici ya da yineleyici bedensel belirtileri", "Yalancı belirtileri", "Yalnızca ağrıyı", "Yalnızca psikotik belirtileri"], "Konversiyon bozukluğunda belirtiler tıbbi patofizyolojiyle açıkça bağdaşmaz.", I("I.1")),
("q935", NG, "Otizm değerlendirmesinde gözlem için öneri nedir?", ["Çocuk yapılandırılmış ve yapılandırılmamış farklı ortamlarda gözlenmelidir", "Yalnızca muayene odasında gözlem yeterlidir", "Gözlem gerekmez", "Yalnızca video izlenir"], "Davranış ortama göre değişir.", I("C.2")),
("q936", DG, "Çocuk haklarına ilişkin araştırma etiğinde çocuk katılımcılar için hangi koşullar aranır?", ["Acı ya da stresin ağır olmaması ve olası zararın geri dönüşlü olması", "Yalnızca ebeveynin ücret alması", "Hiçbir koşul aranmaz", "Çocuğun 18 yaşını doldurması"], "Araştırmacıların yetkin, ortamın uygun olması da gösterilmelidir.", I("A4.1")),
("q937", DG, "İşlevsel başa çıkma becerileri ile işlevsiz savunma düzenekleri arasındaki fark nedir?", ["İlki gerçeklikle baş etmeyi sağlar, ikincisi gerçeklikten kaçınmaya yol açar", "İkisi aynıdır", "İlki yalnızca çocuklarda görülür", "İkincisi her zaman bilinçlidir"], "DSM-IV-TR'nin ekinde uzun bir savunma düzenekleri listesi yer alır.", I("A2.5")),
("q938", PS, "Opioid kullanım bozukluğu olan gence hangi ilaçlar reçete edilebilir?", ["Buprenorfin ya da metadon", "Metilfenidat", "Lityum", "Klozapin"], "Opioidi yakın zamanda kullanmış hastada naltrekson uygun değildir.", I("B4.3")),
("q939", GE, "Mutlak (aşırı) yoksulluk sınırı neyi tanımlar?", ["İnsanların en ağır yoksulluk durumunda yaşadığı düzeyi", "Ortalama gelirin yarısını", "Asgari ücreti", "İşsizlik oranını"], "Toplu olumsuzluk yaşayan çocukların ruh sağlığı bu bağlamda ele alınır.", I("B5.2")),
("q940", DG, "Ruh sağlığı alanının kapsamı için IACAPAP hangi benzetmeyi yapar?", ["Kardiyoloji gibi: yalnızca son evre hastalığa değil, korumaya da bakar", "Cerrahi gibi: yalnızca ameliyata bakar", "Radyoloji gibi: yalnızca görüntüye bakar", "Benzetme yapmaz"], "Kavramsal çerçeve önleme, tedavi ve sürdürmenin yanında ruh sağlığını geliştirmeyi de içermelidir.", I("A.14")),
("q941", DG, "Kalite iyileştirmede ilk koşul nedir?", ["Neyin başarılmak istendiğini ve iyileşmenin nasıl ölçüleceğini netleştirmek", "Yeni bina yapmak", "Personel sayısını azaltmak", "Ölçüm yapmamak"], "Tıbbi girişimlerin yol açtığı hasta zararı ciddiye alınması gereken yaygın bir sorundur.", I("C4.8")),
("q942", NG, "DEHB'de güçlü yönlere odaklanan yaklaşım tedaviyle nasıl ilişkilendirilmelidir?", ["Tedaviye ya da araştırmaya karşıtlık olarak görülmemelidir", "Tedavinin yerini almalıdır", "Tanıyı geçersiz kılar", "Yalnızca erişkinlerde geçerlidir"], "Bireyler ve aileleri DEHB'yle ilişkili güçlükleri gerçekten yaşar.", I("B1.1")),
("q943", NG, "Otizmde yinelenen kopya sayısı değişiklikleri hangi kromozom bölgelerinde bildirilmiştir?", ["15q11-13, 16p11.2 ve 22q11.2 dahil birçok bölgede", "Yalnızca Y kromozomunda", "Yalnızca mitokondri DNA'sında", "Hiçbir bölgede"], "Genetik heterojenliğin göstergesidir.", I("C.2")),
